<?php class DashboardModel {private PDO $pdo;function __construct(PDO $pdo){$this->pdo=$pdo;}function contar($tabla){$permitidas=['estudiantes','profesores','cursos','inscripciones','tutorias'];if(!in_array($tabla,$permitidas,true))return 0;return (int)$this->pdo->query("SELECT COUNT(*) FROM {$tabla}")->fetchColumn();}function promedioNotas(){return (float)$this->pdo->query('SELECT COALESCE(AVG(nota),0) FROM calificaciones')->fetchColumn();}function porcentajeAsistencia(){return (float)$this->pdo->query("SELECT COALESCE(100*SUM(estado='presente')/NULLIF(COUNT(*),0),0) FROM asistencia")->fetchColumn();}function notasPorCurso(){return $this->pdo->query("SELECT c.codigo,c.nombre_curso,ROUND(COALESCE(AVG(cal.nota),0),1) promedio FROM cursos c LEFT JOIN inscripciones i ON i.id_curso=c.id_curso LEFT JOIN calificaciones cal ON cal.id_inscripcion=i.id_inscripcion GROUP BY c.id_curso ORDER BY c.codigo")->fetchAll();}}
